ALTER TABLE public.exhibitions ADD COLUMN IF NOT EXISTS breed text NOT NULL DEFAULT 'Shih Tzu', ADD COLUMN IF NOT EXISTS notes_es text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS notes_en text NOT NULL DEFAULT ''; COMMENT ON COLUMN public.exhibitions.breed IS 'Breed from the verified exhibition source; allows historical Bobtail entries without mislabeling them as Shih Tzu.'; COMMENT ON COLUMN public.exhibitions.notes_es IS 'Additional verified show details, including group judging and Junior Handling, in Spanish.'; COMMENT ON COLUMN public.exhibitions.notes_en IS 'Additional verified show details, including group judging and Junior Handling, in English.';